    int64_t slot = -1;
    int64_t idx = z_t1881_find(_this, _key, h, &slot);
    z_t1093_t _r;
    if (idx < 0) {
        _r.tag = Z_OPTIONVAL_BOOL_TAG_NONE;
        return _r;
    }
    _r.tag = Z_OPTIONVAL_BOOL_TAG_SOME;
    _r.data.some = _this->entries[idx].value;
    z_t46_free(&_this->entries[idx].key);
    _this->entries[idx].alive = 0;
    _this->indices[slot] = Z_T1881_INDEX_DELETED;
    _this->length--;
